export type EmitirDocumentoData = {
    body: FacturaElectronicaRequest | NotaCreditoElectronicaRequest | NotaDebitoElectronicaRequest | NotaRemisionElectronicaRequest | AutofacturaElectronicaRequest;
    headers?: {
        /**
         * Clave opcional para identificar una intención idempotente en operaciones compatibles.
         * Acepta un solo valor de 1 a 255 caracteres ASCII visibles, sin espacios al inicio ni al final.
         * El alcance es por contribuyente y ambiente, compartido entre los tipos de operación.
         * Una clave existente resuelve la operación original sin comparar el body ni el CDC posterior.
         * Otro tipo de operación devuelve 422. El cliente debe persistir la clave y la solicitud original
         * y generar una clave nueva para cada intención nueva. El replay dura 7 días desde la finalización;
         * después la clave sigue reservada hasta que termina la conservación del documento.
         * La solicitud debe poder deserializarse; los campos del body se validan sólo para operaciones nuevas.
         *
         */
        'Idempotency-Key'?: string;
    };
    path?: never;
    query?: never;
    url: '/api/v1/documento-electronico';
};

